/**
 * Макет: «изменение размера для арбитража - 1+2.docx»
 * Вар.6 + опции 1 или 2 + все ответчики юрлица/ИП. Без отсебятины.
 *
 * В том же docx: «Заявление о привлечении соответчиков».
 */
import { formatDutyAmount } from '../utils/calculateStateDuty';
import { addDays, formatRuDate, parseRuDate } from '../utils/calculateHousingPenalty';
import { debtorDisplayName } from '../utils/resolveDebtors';
import {
  resolveAttractCandidates,
  resolveRecalcDefendants,
  resolveRecalcEgrnOwners,
} from './changeClaimDistrict1to8Pdf';

const PLACEHOLDER_COLOR = '#C00000';
/** В образце госпошлина фиксирована: 10 000 руб. */
const ARBITRATION_CHANGE_DUTY = '10\u00a0000';

function label(text) {
  return { text };
}

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

function plain(text) {
  return { text };
}

function field(value, placeholderText) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder(placeholderText || '___');
}

function blank(value) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder('___');
}

function headerLine(children) {
  return { text: children, alignment: 'right' };
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [24, 0, 0, 8] };
}

function moneyField(value, placeholderText) {
  const n = Number(value);
  return n > 0 ? label(formatDutyAmount(n)) : placeholder(placeholderText || 'сумма');
}

function optionalHeaderLine(text) {
  const value = text != null ? String(text).trim() : '';
  return value ? [headerLine([plain(value)])] : [];
}

function penaltyPeriodRange(housingPenalty) {
  const periods = (housingPenalty?.periods || []).filter(
    (p) => !p.excludedAfterAsOf && p.penaltyTotal > 0 && p.segments?.length
  );
  if (!periods.length) return { from: '', to: '' };
  const from = periods[0].segments[0]?.from || periods[0].penaltyStartDate || '';
  const last = periods[periods.length - 1];
  const lastSeg = last.segments[last.segments.length - 1];
  const to = lastSeg?.to || housingPenalty.asOfDate || '';
  return { from, to };
}

function dayAfter(ruDate) {
  const d = parseRuDate(ruDate);
  return d ? formatRuDate(addDays(d, 1)) : '';
}

/** «50», «50%», «50/50» → 50 */
function parseSharePercent(raw) {
  const m = String(raw ?? '')
    .trim()
    .match(/(\d+(?:[.,]\d+)?)/);
  if (!m) return 0;
  const n = Number(String(m[1]).replace(',', '.'));
  return Number.isFinite(n) && n > 0 ? n : 0;
}

function shareAmount(total, sharePercent) {
  const share = parseSharePercent(sharePercent);
  if (!(total > 0) || !(share > 0)) return 0;
  return Math.round(((total * share) / 100 + Number.EPSILON) * 100) / 100;
}

function debtSubjectSentence(requirements) {
  if (requirements === '2') {
    return 'В данном деле с ответчиков взыскивается задолженность по взносам на капитальный ремонт общего имущества в МКД.';
  }
  return 'В данном деле с ответчиков взыскивается задолженность за содержание принадлежащих им помещений в МКД.';
}

function attractDebtSubjectParts(requirements) {
  if (requirements === '2') {
    return plain(
      'В настоящем деле истцом истребуется задолженность по взносам на капитальный ремонт общего имущества в МКД, которая в соответствии с ч. 1 ст. 169 ЖК РФ взыскивается с собственников помещений.'
    );
  }
  return plain(
    'В настоящем деле истцом истребуется задолженность за содержание МКД, которая в соответствии с ч. 1 ст. 39 ЖК РФ взыскивается с собственников помещений.'
  );
}

function defendantHeaderLines(person, indexLabel) {
  const lines = [];
  const name = String(person.fio || '').trim();
  const birthday = String(person.birthday || '').trim();
  const birthplace = String(person.birthplace || '').trim();
  const inn = String(person.inn || '').trim();
  const address = String(person.address || '').trim();
  const prefix = indexLabel ? `${indexLabel}. ` : '';

  if (person.type === 'organization') {
    if (name) lines.push(headerLine([label(prefix), plain(name)]));
    else if (inn) lines.push(headerLine([label(prefix), plain(`ИНН ${inn}`)]));
    else if (prefix) lines.push(headerLine([label(prefix.trim())]));
    if (name && inn) lines.push(headerLine([plain(`ИНН ${inn}`)]));
    if (address) lines.push(headerLine([plain(address)]));
    return lines;
  }

  if (name) lines.push(headerLine([label(prefix), plain(name)]));
  else if (prefix) lines.push(headerLine([label(prefix.trim())]));

  if (birthday || birthplace) {
    const birthParts = [plain('родился (ась) ')];
    if (birthday) birthParts.push(plain(birthday));
    if (birthday && birthplace) birthParts.push(plain(', '));
    if (birthplace) birthParts.push(plain(birthplace));
    lines.push(headerLine(birthParts));
  }
  if (inn) lines.push(headerLine([plain(inn)]));
  if (address) lines.push(headerLine([plain(address)]));
  return lines;
}

function numberedPartyBlocks(list) {
  const multi = list.length > 1;
  return list.flatMap((person, index) => {
    const indexLabel = multi ? String(index + 1) : '';
    const lines = defendantHeaderLines(person, indexLabel);
    return index < list.length - 1 ? [...lines, headerLine([plain(' ')])] : lines;
  });
}

function buildCourtHeader(form, parties) {
  const claimant = form.claimant || {};
  const bank = form.bankDetails || {};
  const court = form.courtDocuments || {};
  const claimantName =
    claimant.type === 'organization'
      ? String(claimant.name || '').trim()
      : String(claimant.name || bank.recipientName || '').trim();
  const claimantInn = String(claimant.inn || bank.inn || '').trim();
  const courtName = String(court.courtName || '').trim();
  const caseNumber = String(court.caseNumber || '').trim();
  const defendantLabel = parties.length > 1 ? 'Ответчики:' : 'Ответчик:';

  return [
    headerLine([label('Арбитражный суд')]),
    ...optionalHeaderLine(courtName),
    headerLine([plain(' ')]),
    headerLine([label('Истец:')]),
    ...optionalHeaderLine(claimantName),
    ...(claimantInn ? [headerLine([plain(`ИНН ${claimantInn}`)])] : []),
    ...optionalHeaderLine(claimant.address),
    headerLine([plain(' ')]),
    headerLine([label(defendantLabel)]),
    ...numberedPartyBlocks(parties),
    headerLine([plain(' ')]),
    headerLine([plain('Дело № '), blank(caseNumber)]),
  ];
}

function collectProshuParagraph(personName, principal, penalty, from, to, continueFrom, dutyText) {
  return bodyParagraph([
    plain('Взыскать с '),
    field(personName, 'такого-то'),
    plain(' задолженность в размере '),
    moneyField(principal, 'сумма'),
    plain(' руб., пеню за период с '),
    blank(from),
    plain(' по '),
    blank(to),
    plain(' в размере '),
    moneyField(penalty, 'сумма'),
    plain(' руб., продолжив начисление пени с '),
    blank(continueFrom),
    plain(' по день фактической оплаты долга '),
    moneyField(principal, 'сумма'),
    plain(
      ' руб., исходя из 1/300 ключевой ставки Банка России от суммы задолженности за каждый день просрочки, а также расходы по уплате госпошлины в размере '
    ),
    label(dutyText),
    plain(' руб.'),
  ]);
}

export function buildChangeClaimArbitration1to2PdfDoc(form = {}) {
  const court = form.courtDocuments || {};
  const reason = String(court.recalculateReason || 'a');
  const requirements = String(form.requirements || '');
  const housingPenalty = (form.skanReport && form.skanReport.housingPenalty) || {};
  const signerFio = form.signer && form.signer.fio;

  const defendants = resolveRecalcDefendants(form);
  const owners = resolveRecalcEgrnOwners(form);

  const principal = Number(housingPenalty.principalTotal) || 0;
  const penaltyTotal = Number(housingPenalty.penaltyTotal) || 0;
  const claimTotal = principal + penaltyTotal;
  const penaltyRange = penaltyPeriodRange(housingPenalty);
  const continueFrom = dayAfter(penaltyRange.to) || penaltyRange.to;
  const dutyText = ARBITRATION_CHANGE_DUTY;

  const content = [
    ...buildCourtHeader(form, defendants),
    {
      text: 'Заявление об изменении размера исковых требований',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },
    bodyParagraph([plain(debtSubjectSentence(requirements))]),
  ];

  if (reason === 'b') {
    content.push(
      bodyParagraph([plain('В настоящее время такая задолженность изменилась,')]),
      bodyParagraph([
        plain('а именно, в связи с неоплатой за новые периоды задолженность выросла до размера '),
        moneyField(principal, 'сумма'),
        plain(' руб., как и изменилась сумма пени согласно ее новому расчету.'),
      ])
    );
  } else if (reason === 'c') {
    content.push(
      bodyParagraph([
        plain(
          'В связи с получением контррасчета ответчика в целях процессуальной экономии в сроках рассмотрения данного дела истец считает необходимым снизить свои требования под контррасчет.'
        ),
      ])
    );
  } else {
    content.push(
      bodyParagraph([plain('В настоящее время такая задолженность изменилась,')]),
      bodyParagraph([
        plain('а именно, в связи с оплатой задолженность уменьшилась до размера '),
        moneyField(principal, 'сумма'),
        plain(' руб., как и изменилась сумма пени согласно ее новому расчету.'),
      ])
    );
  }

  content.push(
    bodyParagraph([
      plain('Всего таким образом, новая сумма указанной задолженности и пени составила '),
      moneyField(claimTotal, 'размер'),
      plain(' руб.'),
    ]),
    bodyParagraph([
      plain('Согласно ч. 1 ст. 49 АПК РФ истец вправе увеличить или уменьшить размер своих требований.'),
    ]),
    bodyParagraph([plain('В связи с чем, руководствуясь ч. 1 ст. 49 АПК РФ,')]),
    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },
    bodyParagraph([
      plain('- принять изменение размера исковых требований до суммы '),
      moneyField(claimTotal, 'размер'),
      plain(' руб.'),
    ])
  );

  const shareParties = owners.length ? owners : defendants;
  for (const person of shareParties.length
    ? shareParties
    : [{ fio: '', inn: '', type: 'organization', ownershipShare: '' }]) {
    const share = parseSharePercent(person.ownershipShare);
    const personPrincipal = share > 0 ? shareAmount(principal, share) : principal;
    const personPenalty = share > 0 ? shareAmount(penaltyTotal, share) : penaltyTotal;
    content.push(
      collectProshuParagraph(
        debtorDisplayName(person),
        personPrincipal,
        personPenalty,
        penaltyRange.from,
        penaltyRange.to,
        continueFrom,
        dutyText
      )
    );
  }

  content.push({ text: 'Приложения:', margin: [24, 12, 0, 4] });
  let n = 1;
  content.push({
    text: `${n++}) почтовые квитанции о направлении заявления в адрес ответчиков,`,
    margin: [24, 0, 0, 0],
  });
  if (reason !== 'c') {
    content.push({ text: `${n++}) выписка по лицевому счету,`, margin: [24, 0, 0, 0] });
    content.push({ text: `${n++}) расчет пени,`, margin: [24, 0, 0, 0] });
  }
  content.push({ text: `${n++}) копия доверенности представителя.`, margin: [24, 0, 0, 0] });

  content.push({ text: [field(signerFio, 'ФИО подписанта')], margin: [24, 24, 0, 0] });

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}

export function buildAttractCodefendantsArbitration1to2PdfDoc(form = {}) {
  const requirements = String(form.requirements || '');
  const defendants = resolveRecalcDefendants(form);
  const owners = resolveRecalcEgrnOwners(form);
  const attract = resolveAttractCandidates(form);
  const signerFio = form.signer && form.signer.fio;
  const list = attract.length ? attract : owners;

  const content = [
    ...buildCourtHeader(form, defendants),
    {
      text: 'Заявление о привлечении соответчиков',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },
    bodyParagraph([attractDebtSubjectParts(requirements)]),
    bodyParagraph([
      plain(
        'Выпиской из ЕГРН подтверждается, что спорные помещения находятся в общедолевой собственности следующих лиц:'
      ),
    ]),
  ];

  for (const owner of owners.length ? owners : [{ fio: '', ownershipShare: '', type: 'organization' }]) {
    content.push(
      bodyParagraph([
        field(debtorDisplayName(owner), 'такого-то'),
        plain(' с долей '),
        blank(owner.ownershipShare),
        plain(' %'),
      ])
    );
  }

  content.push(
    bodyParagraph([
      plain(
        'Согласно ч. 1, п. 1 ч. 2 ст. 46 АПК РФ иск может быть предъявлен к нескольким ответчикам, если предметом спора являются общие обязанности ответчиков.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Для процессуальной экономии во избежание инициирования новых процессов о взыскании той же задолженности с указанных лиц, руководствуясь ч. 1, п. 1 ч. 2 ст. 46 АПК РФ,'
      ),
    ]),
    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },
    bodyParagraph([plain('привлечь к участию в деле в качестве соответчиков:')])
  );

  for (const person of list.length
    ? list
    : [{ type: 'organization', fio: '', birthday: '', birthplace: '', snils: '', address: '', inn: '' }]) {
    if (person.type === 'organization') {
      const name = String(person.fio || '').trim();
      const inn = String(person.inn || '').trim();
      const address = String(person.address || '').trim();
      // наименование; если пусто — только ИНН (без дубля следующей строкой)
      if (name) {
        content.push(bodyParagraph([plain('- '), plain(name)]));
        if (inn) content.push(bodyParagraph([plain(`ИНН ${inn}`)]));
      } else if (inn) {
        content.push(bodyParagraph([plain('- ИНН '), plain(inn)]));
      } else {
        content.push(bodyParagraph([plain('- '), placeholder('наименование')]));
      }
      if (address) content.push(bodyParagraph([plain(address)]));
      continue;
    }

    // ИП / физлицо по образцу — только заполненные поля
    content.push(bodyParagraph([plain('- ИП '), field(person.fio, 'ФИО')]));
    if (String(person.birthday || '').trim()) {
      content.push(bodyParagraph([plain('родился (ась) '), plain(person.birthday), plain(',')]));
    }
    if (String(person.birthplace || '').trim()) {
      content.push(bodyParagraph([plain('место рождения '), plain(person.birthplace)]));
    }
    if (String(person.snils || '').trim()) {
      content.push(bodyParagraph([plain('СНИЛС '), plain(person.snils)]));
    }
    if (String(person.address || '').trim()) {
      content.push(bodyParagraph([plain(person.address)]));
    }
  }

  content.push(
    { text: 'Приложения:', margin: [24, 12, 0, 4] },
    { text: '1) выписка из ЕГРН,', margin: [24, 0, 0, 0] },
    { text: '2) доверенность представителя.', margin: [24, 0, 0, 0] },
    { text: [field(signerFio, 'ФИО подписанта')], margin: [24, 24, 0, 0] }
  );

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
