/**
 * Макет: «исковое для района - с 1 по 8.docx»
 * Ветки опций как у приказа 1–8; роли истец/ответчики; ст. 131–132 ГПК РФ.
 */
import { formatDutyAmount } from '../utils/calculateStateDuty';
import { addDays, formatRuDate, parseRuDate } from '../utils/calculateHousingPenalty';
import { parseRuAddressParts } from '../utils/resolveSoyCourt';
import { debtorDisplayName, joinDebtorNames, resolveDebtors } from '../utils/resolveDebtors';

function label(text) {
  return { text };
}

function plain(text) {
  return { text };
}

const PLACEHOLDER_COLOR = '#C00000';

function placeholder(text) {
  return { text, italics: true, color: PLACEHOLDER_COLOR };
}

/** Пустое значение — ничего не подставляем (без красных плейсхолдеров). */
function field(value) {
  const text = value != null ? String(value).trim() : '';
  return plain(text);
}

/** Значение или красный плейсхолдер (для наименования УК). */
function fieldOrPlaceholder(value, placeholderText) {
  const text = value != null ? String(value).trim() : '';
  return text ? plain(text) : placeholder(placeholderText);
}

function headerLine(children) {
  return { text: children, alignment: 'right' };
}

function bodyParagraph(children) {
  return { text: children, alignment: 'justify', margin: [24, 0, 0, 8] };
}

function moneyField(value) {
  return value > 0 ? label(formatDutyAmount(value)) : plain('');
}

/** Строка шапки только если есть текст. */
function optionalHeaderLine(text) {
  const value = text != null ? String(text).trim() : '';
  return value ? [headerLine([plain(value)])] : [];
}

function penaltyPeriodRange(housingPenalty) {
  const periods = (housingPenalty?.periods || []).filter(
    (p) => !p.excludedAfterAsOf && p.penaltyTotal > 0 && p.segments?.length
  );
  if (!periods.length) return { from: '', to: '' };
  const from = periods[0].segments[0]?.from || periods[0].penaltyStartDate || '';
  const last = periods[periods.length - 1];
  const lastSeg = last.segments[last.segments.length - 1];
  const to = lastSeg?.to || housingPenalty.asOfDate || '';
  return { from, to };
}

/** День после окончания периода пени — «продолжив начисление с …». */
function dayAfter(ruDate) {
  const d = parseRuDate(ruDate);
  return d ? formatRuDate(addDays(d, 1)) : '';
}

function resolveHouseAddress(form, debtor) {
  const requirements = String(form.requirements || '');
  if (requirements === '1' || requirements === '2') {
    return String(form.premisesAddress || '').trim() || String(debtor.address || '').trim();
  }
  if (requirements === '8') {
    return String(form.tkoAddress || '').trim() || String(debtor.address || '').trim();
  }
  return (
    String(form.deliveryAddress || '').trim() ||
    String(debtor.address || '').trim() ||
    String(form.premisesAddress || '').trim() ||
    String(form.tkoAddress || '').trim()
  );
}

function resolveFlatNumber(form, debtor) {
  const fromHouse = resolveHouseAddress(form, debtor);
  const fromDebtor = parseRuAddressParts(debtor.address || '').flat;
  const fromPremises = parseRuAddressParts(fromHouse).flat;
  const flat = fromPremises || fromDebtor;
  if (flat) {
    return flat.replace(/^(кв\.|квартира)\s*/i, '').trim() || flat;
  }
  const match = fromHouse.match(/(?:кв\.|квартира)\s*([0-9A-Za-zА-Яа-я/-]+)/i);
  return match ? match[1] : '';
}

/** Как в образце иска: «родился (ась) …» + ИНН — строки без значений пропускаем. */
function defendantHeaderLines(person, houseAddress) {
  const name = String(person.fio || '').trim();
  const address = String(person.address || houseAddress || '').trim();
  const birthday = String(person.birthday || '').trim();
  const birthplace = String(person.birthplace || '').trim();
  const inn = String(person.inn || '').trim();
  const lines = [];

  if (name) lines.push(headerLine([plain(name)]));

  if (person.type === 'organization') {
    if (inn) lines.push(headerLine([plain(inn)]));
    if (address) lines.push(headerLine([plain(address)]));
    return lines;
  }

  if (birthday || birthplace) {
    const birthParts = [plain('родился (ась) ')];
    if (birthday) birthParts.push(plain(birthday));
    if (birthday && birthplace) birthParts.push(plain(', '));
    if (birthplace) birthParts.push(plain(birthplace));
    lines.push(headerLine(birthParts));
  }
  if (inn) lines.push(headerLine([plain(inn)]));
  if (address) lines.push(headerLine([plain(address)]));
  return lines;
}

/**
 * Ветки как в «приказ … 1 по 8» / «исковое … 1 по 8»:
 * опция 1 / (3.1…8 при 1 лице); опция 2; 3.1…8 при 2+; затем 1/300 или 1/130.
 */
function buildPenaltyDutyParagraphs(requirements, debtorCount) {
  const isOpt2 = requirements === '2';
  const isTko = requirements === '8';
  const utilityOpts = ['3.1', '5.1', '6.1', '6.3', '7.1', '8'].includes(requirements);
  const solidary = utilityOpts && debtorCount >= 2;
  const paragraphs = [];

  if (solidary) {
    paragraphs.push(
      bodyParagraph([
        plain(
          'В связи с чем своевременная оплата такой задолженности является солидарной обязанностью собственника и совершеннолетних членов его семьи.'
        ),
      ])
    );
    paragraphs.push(
      bodyParagraph([
        plain(
          'Поскольку данная задолженность ими просрочена, частью 14 статьи 155 ЖК РФ для собственника и совершеннолетних членов его семьи, несвоевременно и (или) не полностью внесших плату за жилое помещение и коммунальные услуги,'
        ),
      ])
    );
  } else if (isOpt2) {
    paragraphs.push(
      bodyParagraph([
        plain('В связи с чем своевременная оплата такой задолженности является обязанностью собственника.'),
      ])
    );
    paragraphs.push(
      bodyParagraph([
        plain(
          'Поскольку данная задолженность им просрочена, частью 14.1 статьи 155 ЖК РФ для собственника, несвоевременно и (или) не полностью уплатившего взносы на капитальный ремонт,'
        ),
      ])
    );
  } else {
    paragraphs.push(
      bodyParagraph([
        plain('В связи с чем своевременная оплата такой задолженности является обязанностью собственника.'),
      ])
    );
    paragraphs.push(
      bodyParagraph([
        plain(
          'Поскольку данная задолженность им просрочена, частью 14 статьи 155 ЖК РФ для собственника, несвоевременно и (или) не полностью внесшего плату за жилое помещение и коммунальные услуги,'
        ),
      ])
    );
  }

  if (isTko) {
    paragraphs.push(
      bodyParagraph([
        plain(
          'предусмотрена законная пеня в размере 1/130 ключевой ставки Банка России от невыплаченной в срок суммы за каждый день просрочки, начиная со следующего дня после установленного срока оплаты по день фактической оплаты.'
        ),
      ])
    );
  } else {
    paragraphs.push(
      bodyParagraph([
        plain(
          'предусмотрена законная пеня в размере 1/300 ключевой ставки Банка России от невыплаченной в срок суммы за каждый день просрочки, начиная с 31 дня, следующего за днем наступления установленного срока оплаты, по день фактической оплаты.'
        ),
      ])
    );
  }

  return paragraphs;
}

export function buildStatementDistrict1to8PdfDoc(form = {}) {
  const claimant = form.claimant || {};
  const bank = form.bankDetails || {};
  const debtors = resolveDebtors(form);
  const debtor = debtors[0] || {};
  const signerFio = form.signer && form.signer.fio;
  const housingPenalty = (form.skanReport && form.skanReport.housingPenalty) || {};
  const stateDuty = (form.skanReport && form.skanReport.stateDuty) || {};
  const dutyAmount = stateDuty.amount > 0 ? formatDutyAmount(stateDuty.amount) : null;
  const claimantName = String(claimant.name || bank.recipientName || '').trim();
  const claimantInn = String(claimant.inn || bank.inn || '').trim();
  const requirements = String(form.requirements || '');
  const isTko = requirements === '8';
  const rateLabel = isTko ? '1/130' : '1/300';

  const debtorFios = joinDebtorNames(debtors);
  const ownerFio = debtorDisplayName(debtor);
  const coOwnerFios = debtors.length > 1 ? joinDebtorNames(debtors.slice(1)) : '';
  const houseAddress = resolveHouseAddress(form, debtor);
  const flatNumber = resolveFlatNumber(form, debtor);
  const penaltyRange = penaltyPeriodRange(housingPenalty);
  const continueFrom = dayAfter(penaltyRange.to) || penaltyRange.to;
  const hasDebt = Number(housingPenalty.principalTotal) > 0;
  const appendixEgrn =
    requirements === '1' || requirements === '2' || debtors.length < 2;

  // Без должников (опции 1–2 + «выписка не запрашивалась») — шапка Ответчик пустая, без адреса МКД
  const defendantBlocks = debtors.flatMap((d, index) => {
    const lines = defendantHeaderLines(d, houseAddress);
    return index < debtors.length - 1 ? [...lines, headerLine([plain(' ')])] : lines;
  });

  const content = [
    headerLine([label('Районному судье')]),
    headerLine([plain(' ')]),
    headerLine([label('Истец:')]),
    ...optionalHeaderLine(claimantName),
    ...(claimantInn ? [headerLine([plain('ИНН '), plain(claimantInn)])] : []),
    ...optionalHeaderLine(claimant.address),
    headerLine([plain(' ')]),
    headerLine([label('Ответчик:')]),
    ...defendantBlocks,

    {
      text: 'Исковое заявление',
      alignment: 'center',
      bold: true,
      margin: [0, 24, 0, 24],
    },

    bodyParagraph([
      fieldOrPlaceholder(claimantInn, 'такая-то'),
      plain(' исполняет обязанности по управлению и текущему ремонту в отношении многоквартирного дома по адресу: '),
      field(houseAddress),
      plain('.'),
    ]),
    bodyParagraph([
      field(ownerFio),
      plain(' является собственником квартиры '),
      field(flatNumber),
      plain(' в этом доме.'),
    ]),
    ...(coOwnerFios
      ? [
          bodyParagraph([
            plain('Совместно с ним зарегистрированы совершеннолетние '),
            plain(coOwnerFios),
            plain('.'),
          ]),
          bodyParagraph([
            plain(
              'На основании ч. 2 ст. 30, ч. 2 ст. 31 ЖК РФ собственник вправе вселить в свое жилое помещение других граждан, являющихся членами его семьи.'
            ),
          ]),
          bodyParagraph([
            plain(
              'В связи с чем факт их совместной регистрации с собственником указывает на принадлежность их к семье собственника спорной квартиры.'
            ),
          ]),
        ]
      : []),
    bodyParagraph([
      plain(
        'Согласно ч. 1 ст. 155 ЖК РФ плата за жилое помещение и коммунальные услуги вносится ежемесячно до пятнадцатого числа месяца, следующего за истекшим месяцем.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Данная плата для собственника включает в себя: 1) плату за содержание жилого помещения, 2) взнос на капитальный ремонт, 3) плату за коммунальные услуги (ч. 2 ст. 154 ЖК РФ).'
      ),
    ]),
    bodyParagraph([
      plain(
        'Дееспособные и ограниченные в дееспособности члены семьи собственника несут солидарную с собственником обязанность по своевременному внесению платы за жилое помещение и коммунальные услуги (ч. 3 ст. 31 ЖК РФ + п. 1 ст. 21 ГК РФ).'
      ),
    ]),
    bodyParagraph([
      plain(
        'При солидарной обязанности должников кредитор вправе требовать исполнения как от всех должников совместно, так и от любого из них в отдельности, притом как полностью, так и в части долга (п. 1 ст. 323 ГК РФ).'
      ),
    ]),
    bodyParagraph([
      plain('Как следует из выписки по лицевому счету, по квартире '),
      field(flatNumber),
      plain(' числится задолженность за услуги по управлению и текущему ремонту общего имущества в размере '),
      moneyField(housingPenalty.principalTotal),
      plain(' руб.'),
    ]),
    ...buildPenaltyDutyParagraphs(requirements, debtors.length),
    bodyParagraph([
      plain('По расчету истца (прилагается) сумма такой пени составляет '),
      moneyField(housingPenalty.penaltyTotal),
      plain(' руб.'),
    ]),
    // Образец: вставка при наличии задолженности
    ...(hasDebt
      ? [
          bodyParagraph([
            plain(
              'По смыслу ст. 330 ГК РФ, истец вправе требовать присуждения неустойки по день фактического исполнения обязательства, о чем указано в п. 65 Постановления Пленума Верховного Суда РФ от 24.03.2016 № 7.'
            ),
          ]),
        ]
      : []),
    bodyParagraph([
      plain('В соответствии с абз. 2 п. 5 постановления Пленума Верховного Суда РФ от 21.01.2016 № 1,'),
    ]),
    bodyParagraph([
      plain(
        'если лица, не в пользу которых принят судебный акт, являются солидарными должниками, судебные издержки возмещаются указанными лицами в солидарном порядке.'
      ),
    ]),
    bodyParagraph([
      plain(
        'Исходя из этого госпошлина за предъявление одним кредитором к нескольким солидарным должникам требований о взыскании общей задолженности и пени уплачивается как за одно требование, т.к. обязательство для таких должников перед кредитором является единым (п. 1 ст. 323 ГК РФ).'
      ),
    ]),
    bodyParagraph([plain('На основании изложенного, а также ст. 131, 132 ГПК РФ,')]),

    { text: 'ПРОШУ:', alignment: 'center', bold: true, margin: [0, 12, 0, 12] },

    bodyParagraph([
      plain('- взыскать в солидарном порядке с '),
      field(debtorFios),
      plain(' задолженность в размере '),
      moneyField(housingPenalty.principalTotal),
      plain(' руб., пеню за период с '),
      field(penaltyRange.from),
      plain(' по '),
      field(penaltyRange.to),
      plain(' в размере '),
      moneyField(housingPenalty.penaltyTotal),
      plain(' руб., продолжив начисление пени с '),
      field(continueFrom),
      plain(' по день фактической оплаты долга '),
      moneyField(housingPenalty.principalTotal),
      plain(' руб., исходя из '),
      plain(rateLabel),
      plain(
        ' ключевой ставки Банка России от суммы задолженности за каждый день просрочки, а также расходы по уплате госпошлины в размере '
      ),
      dutyAmount ? label(dutyAmount) : plain(''),
      plain(' руб.'),
    ]),

    { text: 'Приложения:', margin: [24, 12, 0, 4] },
    { text: '1) почтовые квитанции о направлении заявления в адрес ответчиков,', margin: [24, 0, 0, 0] },
    {
      text: [
        plain('2) доказательства уплаты госпошлины в размере '),
        dutyAmount ? label(dutyAmount) : plain(''),
        plain(' руб.,'),
      ],
      margin: [24, 0, 0, 0],
    },
    { text: '3) выписка по лицевому счету,', margin: [24, 0, 0, 0] },
    { text: '4) расчет пени,', margin: [24, 0, 0, 0] },
    {
      text: appendixEgrn
        ? '5) выписка из ЕГРН,'
        : '5) справка о лицах, зарегистрированных в спорной квартире,',
      margin: [24, 0, 0, 0],
    },
    { text: '6) копия доверенности представителя.', margin: [24, 0, 0, 0] },

    ...(signerFio ? [{ text: [field(signerFio)], margin: [24, 24, 0, 0] }] : []),
  ];

  return {
    content,
    defaultStyle: { fontSize: 11 },
    pageMargins: [56, 56, 56, 56],
  };
}
