/**
 * Долг по кредиту (опция 9) — как в примере заказчика (колонки «просроченный осн долг» / «просроченные %»):
 * - график[i] ↔ блок выписки[i];
 * - оплаты блока списываются по очередности: просроч.% → просроч.ОД → тек.% → тек.ОД;
 * - жёлтый: просроченный ОД прошлых периодов (после оплат блока, до добавления текущего ОД);
 * - красный: жёлтый + ОД и % текущего периода (после переноса остатка).
 */

function toAmount(value) {
  if (value == null || value === '' || value === '-' || value === '---') return 0;
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
  let s = String(value).replace(/\u00a0/g, '').replace(/\s/g, '').trim();
  if (!s || s === '-' || s === '---') return 0;
  if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) s = s.replace(/,/g, '');
  else if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, '').replace(',', '.');
  else if (s.includes(',') && s.includes('.')) {
    s =
      s.lastIndexOf(',') > s.lastIndexOf('.')
        ? s.replace(/\./g, '').replace(',', '.')
        : s.replace(/,/g, '');
  } else if (s.includes(',')) s = s.replace(',', '.');
  const num = Number(s);
  return Number.isFinite(num) ? num : 0;
}

function roundMoney(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function take(balance, rest) {
  if (rest <= 0 || balance <= 0) return { balance, rest };
  const x = Math.min(rest, balance);
  return { balance: roundMoney(balance - x), rest: roundMoney(rest - x) };
}

/** Списание одной суммы по законной очередности. */
export function applyLegalAllocation(state, amount) {
  let rest = toAmount(amount);
  ({ balance: state.overdueInterest, rest } = take(state.overdueInterest, rest));
  ({ balance: state.overduePrincipal, rest } = take(state.overduePrincipal, rest));
  ({ balance: state.currentInterest, rest } = take(state.currentInterest, rest));
  ({ balance: state.currentPrincipal, rest } = take(state.currentPrincipal, rest));
  return rest;
}

export function emptyLoanAllocationState() {
  return {
    overdueInterest: 0,
    overduePrincipal: 0,
    currentInterest: 0,
    currentPrincipal: 0,
  };
}

/**
 * Прогон периодов график ↔ выписка.
 * @returns {{ periods: object[], overduePrincipal: number, overdueInterest: number, overdueTotal: number, overduePrincipalPast: number }}
 */
export function simulateLoanAllocation(paymentSchedule, legalAccountRows) {
  const schedulePayments = paymentSchedule?.payments || [];
  const ledgerPeriods = legalAccountRows?.periods || [];
  const count = Math.min(schedulePayments.length, ledgerPeriods.length);
  const state = emptyLoanAllocationState();
  const periods = [];

  for (let i = 0; i < count; i += 1) {
    const install = schedulePayments[i];
    const interest = toAmount(install.interest);
    const principal = toAmount(install.principal);
    const total = toAmount(install.total) || roundMoney(interest + principal);
    if (!(total > 0)) continue;

    state.currentInterest = roundMoney(state.currentInterest + interest);
    state.currentPrincipal = roundMoney(state.currentPrincipal + principal);

    const periodPayments = (ledgerPeriods[i]?.payments || []).map((p) => ({
      date: p.date,
      amount: toAmount(p.amount),
      label: p.label || '',
    }));

    for (const payment of periodPayments) {
      if (payment.amount > 0) applyLegalAllocation(state, payment.amount);
    }

    // жёлтый: просроченный ОД прошлых периодов после оплат, до переноса текущего ОД
    const overduePrincipalPast = state.overduePrincipal;

    state.overdueInterest = roundMoney(state.overdueInterest + state.currentInterest);
    state.overduePrincipal = roundMoney(state.overduePrincipal + state.currentPrincipal);
    state.currentInterest = 0;
    state.currentPrincipal = 0;

    periods.push({
      index: i,
      dueDate: install.date,
      total,
      principal,
      interest,
      overduePrincipalPast,
      overduePrincipal: state.overduePrincipal,
      overdueInterest: state.overdueInterest,
      overdueTotal: roundMoney(state.overduePrincipal + state.overdueInterest),
      payments: periodPayments,
    });
  }

  return {
    periods,
    overduePrincipal: state.overduePrincipal,
    overdueInterest: state.overdueInterest,
    overdueTotal: roundMoney(state.overduePrincipal + state.overdueInterest),
    overduePrincipalPast: periods.length ? periods[periods.length - 1].overduePrincipalPast : 0,
  };
}

/**
 * Суммы для PDF опции 9.
 * remainingCredit = просроченный ОД (красная колонка ОД),
 * overdueInterest = просроченные % (красная колонка %).
 */
export function calculateLoanDebt(paymentSchedule, legalAccountRows) {
  const schedule = paymentSchedule || {};
  const ledger = legalAccountRows || {};
  if (!(schedule.payments || []).length || !(ledger.periods || []).length) return null;

  const sim = simulateLoanAllocation(schedule, ledger);
  const outgoing = Number(ledger.meta?.outgoingBalance);
  const overdueTotal =
    Number.isFinite(outgoing) && outgoing > 0 ? roundMoney(outgoing) : sim.overdueTotal;

  return {
    asOfDate: String(ledger.meta?.asOfDate || '').trim(),
    creditAmount: Number(schedule.creditAmount) || 0,
    annualRatePercent: schedule.annualRatePercent,
    termLabel: schedule.termLabel || '',
    overdueTotal,
    overdueInterest: sim.overdueInterest,
    remainingCredit: sim.overduePrincipal,
    overduePrincipalPast: sim.overduePrincipalPast,
    periods: sim.periods,
  };
}
